function generateAndSolveMaze(canvasId) {
    try {
        const canvas = document.getId(canvasId);
        if (!canvas || canvas.width !== 500 || canvas.height !== 500) throw new Error('Canvas not found or wrong size');
        const ctx = canvas.getContext('2d');
        const N = 51; // odd grid size for walls
        const cellSize = 10;
        const grid = Array.from({ length: N }, () => Array(N).fill(1));
        const state = Array.from({ length: N }, () => Array(N).fill(1));
        const overlay = Array.from({ length: N }, () => Array(N).fill(null));

        // Initialize walls around the maze
        for (let i = 0; i < N; i++) {
            grid[i][0] = grid[i][N - 1] = 0;
            grid[0][i] = grid[N - 1][i] = 0;
            state[i][0] = state[i][N - 1] = 0;
            state[0][i] = state[N - 1][i] = 0;
        }
        // Entrance and exit
        grid[1][0] = grid[N - 2][N - 1] = 1;
        state[1][0] = state[N - 2][N - 1] = 1;
        // Steps for generation
        const genSteps = [];
        function addStep(x, y, val) {
            if (grid[x][y] !== val) {
                grid[x][y] = val;
                genSteps.push({ x, y, val });
            }
        }
        function divide(x1, y1, x2, y2) {
            const width = x2 - x1;
            const height = y2 - y1;
            if (width < 2 || height < 2) return;
            const horizontal = width < height;
            if (horizontal) {
                const wx = x1 + 1 + Math.floor((Math.floor(width / 2)) * 2);
                if (wx > x2 - 1) return;
                const wy = y1;
                const passage = y1 + 1 + Math.floor((Math.floor(height / 2)) * 2);
                for (let i = x1; i <= x2; i++) addStep(i, wx, 0);
                addStep(passage, wx, 1);
                divide(x1, y1, x2, wx - 1);
                divide(x1, wx + 1, x2, y2);
            } else {
                const wy = y1 + 1 + Math.floor((Math.floor(height / 2)) * 2);
                if (wy > y2 - 1) return;
                const wx = x1;
                const passage = x1 + 1 + Math.floor((Math.floor(width / 2)) * 2);
                for (let i = y1; i <= y2; i++) addStep(wx, i, 0);
                addStep(wx, passage, 1);
                divide(x1, y1, wx - 1, y2);
                divide(wx + 1, y1, x2, y2);
            }
        }
        // Generate maze
        divide(1, 1, N - 2, N - 2);

        // Drawing routine
        function draw() {
            for (let y = 0; y < N; y++) {
                for (let x = 0; x < N; x++) {
                    let color = 'white';
                    if (grid[x][y] === 0) color = 'black';
                    if (overlay[x][y] === 'current') color = 'red';
                    else if (overlay[x][y] === 'closed') color = 'gray';
                    else if (overlay[x][y] === 'open') color = 'yellow';
                    else if (overlay[x][y] === 'solution') color = 'blue';
                    ctx.fillStyle = color;
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                }
            }
        }

        // Animate generation
        let genIndex = 0;
        const genTimer = setInterval(() => {
            if (genIndex >= genSteps.length) {
                clearInterval(genTimer);
                draw();
                startSolving();
                return;
            }
            const step = genSteps[genIndex++];
            grid[step.x][step.y] = step.val;
            draw();
        }, 10);

        // A* solving
        function startSolving() {
            const start = { x: 1, y: 0 };
            const goal = { x: N - 2, y: N - 1 };
            const openSet = [];
            const openMap = new Map();
            const closedSet = new Set();
            const cameFrom = new Map();
            const gScore = new Map();
            function key(x, y) { return x + ',' + y; }
            const startKey = key(start.x, start.y);
            gScore.set(startKey, 0);
            const hStart = Math.abs(start.x - goal.x) + Math.abs(start.y - goal.y);
            openSet.push({ x: start.x, y: start.y, f: hStart, g: 0, h: hStart });
            openMap.set(startKey, openSet[0]);

            function reconstruct(pathKey) {
                let curr = pathKey;
                while (curr) {
                    const [x, y] = curr.split(',').map(Number);
                    overlay[x][y] = 'solution';
                    curr = cameFrom.get(curr);
                }
                draw();
            }

            const solveTimer = setInterval(() => {
                if (openSet.length === 0) {
                    clearInterval(solveTimer);
                    return; // no path
                }
                // current node
                let currentIdx = 0;
                for (let i = 1; i < openSet.length; i++) if (openSet[i].f < openSet[currentIdx].f) currentIdx = i;
                const current = openSet.splice(currentIdx, 1)[0];
                openMap.delete(key(current.x, current.y));
                overlay[current.x][current.y] = 'current';
                draw();

                const currentKey = key(current.x, current.y);
                closedSet.add(currentKey);
                overlay[current.x][current.y] = 'closed';

                if (current.x === goal.x && current.y === goal.y) {
                    clearInterval(solveTimer);
                    reconstruct(currentKey);
                    return;
                }

                const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
                for (const [dx, dy] of dirs) {
                    const nx = current.x + dx;
                    const ny = current.y + dy;
                    if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
                    if (grid[nx][ny] === 0) continue;
                    const neighborKey = key(nx, ny);
                    if (closedSet.has(neighborKey)) continue;
                    const tentativeG = current.g + 1;
                    if (!openMap.has(neighborKey) || tentativeG < gScore.get(neighborKey)) {
                        cameFrom.set(neighborKey, currentKey);
                        gScore.set(neighborKey, tentativeG);
                        const h = Math.abs(nx - goal.x) + Math.abs(ny - goal.y);
                        const f = tentativeG + h;
                        const neighborNode = { x: nx, y: ny, g: tentativeG, h: h, f: f };
                        openSet.push(neighborNode);
                        openMap.set(neighborKey, neighborNode);
                        if (!overlay[nx][ny]) overlay[nx][ny] = 'open';
                    }
                }
                draw();
            }, 20);
        }
    } catch (e) {
        console.error('Maze generation error:', e);
    }
}
